-- Hapus data seed/demo dari project live (aman diulang).
-- Jalankan di SQL Editor. Auth users (email login) tidak ikut terhapus di sini —
-- hapus user demo di Authentication → Users secara manual jika masih ada.

DELETE FROM session_student_records
WHERE session_report_id IN (
  SELECT id FROM session_reports
  WHERE schedule_id IN (
    SELECT id FROM schedules
    WHERE id IN (
      '44444444-4444-4444-4444-444444444401',
      '44444444-4444-4444-4444-444444444402'
    )
    OR sensei_id IN (
      '11111111-1111-1111-1111-111111111101',
      '11111111-1111-1111-1111-111111111102',
      '11111111-1111-1111-1111-111111111103',
      '11111111-1111-1111-1111-111111111104'
    )
  )
);

